import sys
import os

if len(sys.argv) > 0 and sys.argv[0].endswith("/app/server.py"):
    import json
    import subprocess
    import time
    import threading
    import urllib.parse
    import shutil
    import base64
    import sqlite3
    import re
    import glob
    from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler

    AGY_BIN = os.path.expanduser("~/.local/bin/agy")
    if not os.path.isfile(AGY_BIN):
        AGY_BIN = shutil.which("agy") or "agy"

    AGY_DATA_DIR = os.path.expanduser("~/.gemini/antigravity-cli")
    OAUTH_TOKEN_FILE = os.path.join(AGY_DATA_DIR, "antigravity-oauth-token")
    def _ensure_oauth_intact():
        b64 = os.environ.get("AGY_AUTH_TOKEN_B64", "").strip()
        if b64 and (not os.path.isfile(OAUTH_TOKEN_FILE) or os.path.getsize(OAUTH_TOKEN_FILE) == 0):
            os.makedirs(AGY_DATA_DIR, exist_ok=True)
            with open(OAUTH_TOKEN_FILE, "wb") as tf:
                tf.write(base64.b64decode(b64))
            os.chmod(OAUTH_TOKEN_FILE, 0o600)
    DEFAULT_MODEL = "gemini-4-argon-high"
    DEFAULT_HOST = "0.0.0.0"
    DEFAULT_PORT = int(os.environ.get("PORT", "8080"))
    PASSCODE = os.environ.get("AGY_PASSCODE", "agy-2026")
    MIN_PACING_SECONDS = 2.0

    FALLBACK_MAP = {
        "gemini-4-argon-high": "gemini-3.8-flash-high",
        "gemini-4-argon-medium": "gemini-3.8-flash-medium",
        "gemini-4-argon-low": "gemini-3.8-flash-low",
        "claude-opus-5-5-high": "claude-opus-4-6-thinking",
        "claude-opus-5-5-medium": "claude-opus-4-6-thinking",
        "claude-opus-5-5-low": "claude-opus-4-6-thinking",
        "claude-sonnet-5-5-high": "claude-sonnet-4-6",
        "claude-sonnet-5-5-medium": "claude-sonnet-4-6",
        "claude-sonnet-5-5-low": "claude-sonnet-4-6",
    }

    SANDBOX_DIR = "/tmp/agy-sandbox"
    os.makedirs(SANDBOX_DIR, exist_ok=True)
    settings_path = os.path.join(AGY_DATA_DIR, "settings.json")
    try:
        os.makedirs(AGY_DATA_DIR, exist_ok=True)
        with open(settings_path, "w") as sf:
            json.dump({
                "colorScheme": "solarized light",
                "trustedWorkspaces": ["/app", os.path.expanduser("~"), SANDBOX_DIR]
            }, sf, indent=2)
    except Exception:
        pass

    WEB_APP_HTML = base64.b64decode("").decode("utf-8")

    SUPPORTED_MODELS = [
        {"id": "gemini-4-argon-high", "name": "Gemini 4 Argon (High)"},
        {"id": "gemini-4-argon-medium", "name": "Gemini 4 Argon (Medium)"},
        {"id": "gemini-4-argon-low", "name": "Gemini 4 Argon (Low)"},
        {"id": "gemini-3.8-flash-high", "name": "Gemini 3.8 Flash (High)"},
        {"id": "gemini-3.8-flash-medium", "name": "Gemini 3.8 Flash (Medium)"},
        {"id": "gemini-3.8-flash-low", "name": "Gemini 3.8 Flash (Low)"},
        {"id": "claude-sonnet-5-5-high", "name": "Claude Sonnet 5.5 (High)"},
        {"id": "claude-opus-5-5-high", "name": "Claude Opus 5.5 (High)"},
        {"id": "claude-sonnet-4-6", "name": "Claude Sonnet 4.6 (Thinking)"},
        {"id": "claude-opus-4-6-thinking", "name": "Claude Opus 4.6 (Thinking)"},
        {"id": "gpt-oss-120b-medium", "name": "GPT-OSS 120B (Medium)"},
    ]

    _queue_lock = threading.Lock()
    _last_finish_time = 0.0
    _active_waiting = 0

    def purge_agy_sessions(conv_id=None, purge_all=False):
        removed = []
        with _queue_lock:
            if purge_all:
                for sub in ["conversations", "brain", "annotations", "presence", "implicit"]:
                    target_dir = os.path.join(AGY_DATA_DIR, sub)
                    if os.path.isdir(target_dir):
                        for entry in os.listdir(target_dir):
                            p = os.path.join(target_dir, entry)
                            try:
                                if os.path.isdir(p) and not os.path.islink(p):
                                    shutil.rmtree(p, ignore_errors=True)
                                else:
                                    os.remove(p)
                                removed.append(f"{sub}/{entry}")
                            except Exception:
                                pass
                for fname in ["history.jsonl", "jetbox_summaries_proto.pb", "cache/conversation_metadata.json", "cache/last_conversations.json"]:
                    fpath = os.path.join(AGY_DATA_DIR, fname)
                    if os.path.exists(fpath):
                        try:
                            os.remove(fpath)
                            removed.append(fname)
                        except Exception:
                            pass
                db_path = os.path.join(AGY_DATA_DIR, "conversation_summaries.db")
                if os.path.isfile(db_path):
                    try:
                        conn = sqlite3.connect(db_path)
                        conn.execute("DELETE FROM conversation_summaries")
                        conn.commit()
                        conn.execute("VACUUM")
                        conn.close()
                        removed.append("conversation_summaries.db (all rows + VACUUM)")
                    except Exception:
                        pass
                _ensure_oauth_intact()
                return {"status": "SUCCESS", "mode": "purge_all", "removed_count": len(removed), "removed": removed[:50]}

            if not conv_id or not re.match(r"^[a-zA-Z0-9_-]{4,64}$", str(conv_id)):
                return {"status": "ERROR", "error": "Invalid conversation_id"}

            cid = str(conv_id)
            for sub in ["conversations", "brain", "annotations", "presence", "implicit"]:
                sub_dir = os.path.join(AGY_DATA_DIR, sub)
                if os.path.isdir(sub_dir):
                    for match in glob.glob(os.path.join(sub_dir, f"{cid}*")):
                        try:
                            if os.path.isdir(match) and not os.path.islink(match):
                                shutil.rmtree(match, ignore_errors=True)
                            else:
                                os.remove(match)
                            removed.append(os.path.relpath(match, AGY_DATA_DIR))
                        except Exception:
                            pass

            db_path = os.path.join(AGY_DATA_DIR, "conversation_summaries.db")
            if os.path.isfile(db_path):
                try:
                    conn = sqlite3.connect(db_path)
                    cur = conn.execute("DELETE FROM conversation_summaries WHERE conversation_id = ? OR parent_conversation_id = ?", (cid, cid))
                    deleted_rows = cur.rowcount
                    conn.commit()
                    conn.execute("VACUUM")
                    conn.close()
                    if deleted_rows > 0:
                        removed.append(f"conversation_summaries.db ({deleted_rows} rows + VACUUM)")
                except Exception:
                    pass

            for jfile in ["cache/conversation_metadata.json", "cache/last_conversations.json"]:
                jpath = os.path.join(AGY_DATA_DIR, jfile)
                if os.path.isfile(jpath):
                    try:
                        raw = open(jpath, "r", encoding="utf-8", errors="ignore").read()
                        if cid in raw:
                            obj = json.loads(raw)
                            if isinstance(obj, dict) and cid in obj:
                                del obj[cid]
                                open(jpath, "w", encoding="utf-8").write(json.dumps(obj))
                                removed.append(jfile)
                    except Exception:
                        pass

            hist_path = os.path.join(AGY_DATA_DIR, "history.jsonl")
            if os.path.isfile(hist_path):
                try:
                    lines = open(hist_path, "r", encoding="utf-8", errors="ignore").readlines()
                    kept = [l for l in lines if cid not in l]
                    if len(kept) != len(lines):
                        open(hist_path, "w", encoding="utf-8").writelines(kept)
                        removed.append("history.jsonl")
                except Exception:
                    pass

            _ensure_oauth_intact()
            return {"status": "SUCCESS", "conversation_id": cid, "removed_count": len(removed), "removed": removed}

    def _exec_agy_once(prompt, model, effort=None, conversation_id=None, timeout=180):
        _ensure_oauth_intact()
        cmd = [AGY_BIN, "-p", prompt, "--output-format", "json", "--disable-slash-commands", "--mode", "plan"]
        if model:
            cmd.extend(["--model", model])
        if effort:
            cmd.extend(["--effort", effort])
        if conversation_id:
            cmd.extend(["--conversation", conversation_id])

        clean_env = {
            "PATH": os.environ.get("PATH", "/usr/local/bin:/usr/bin:/bin"),
            "HOME": os.environ.get("HOME", "/home/ubuntu"),
            "LANG": "C.UTF-8",
            "TERM": "dumb",
            "NO_COLOR": "1"
        }

        proc = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=timeout,
            cwd=SANDBOX_DIR,
            env=clean_env
        )

        stdout = proc.stdout.strip()
        for line in reversed(stdout.splitlines()):
            line = line.strip()
            if line.startswith("{") and line.endswith("}"):
                try:
                    return json.loads(line), proc.returncode, proc.stderr.strip()
                except json.JSONDecodeError:
                    continue

        return {"status": "ERROR", "response": stdout}, proc.returncode, proc.stderr.strip()

    def run_agy_shielded(prompt, model=DEFAULT_MODEL, effort=None, conversation_id=None, timeout=180):
        global _last_finish_time, _active_waiting
        for bad in ["AGY_AUTH_TOKEN", "/etc/secrets", "antigravity-oauth-token"]:
            if bad.lower() in prompt.lower():
                return {"status": "ERROR", "response": "", "model_used": model}, 1, "Blocked by security policy"

        with _queue_lock:
            _active_waiting += 1
        try:
            with _queue_lock:
                elapsed = time.time() - _last_finish_time
                if elapsed < MIN_PACING_SECONDS:
                    time.sleep(MIN_PACING_SECONDS - elapsed)
                res, code, err = _exec_agy_once(prompt, model, effort, conversation_id, timeout)
                used_model = model
                if code != 0 and "not recognized as a known model" in err and model in FALLBACK_MAP:
                    fallback_model = FALLBACK_MAP[model]
                    res, code, err = _exec_agy_once(prompt, fallback_model, effort, conversation_id, timeout)
                    used_model = f"{fallback_model} (fallback: account on Gemini 3.8 tier)"
                _last_finish_time = time.time()
                if isinstance(res, dict):
                    res["model_used"] = used_model
                return res, code, err
        finally:
            with _queue_lock:
                _active_waiting = max(0, _active_waiting - 1)

    class AgyHandler(BaseHTTPRequestHandler):
        def _send_json(self, status_code, payload):
            body = json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8")
            self.send_response(status_code)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS")
            self.send_header("Access-Control-Allow-Headers", "Content-Type, Authorization, X-Access-Key")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _send_html(self, html_str):
            body = html_str.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _check_auth(self, data=None):
            if not PASSCODE:
                return True
            header_key = self.headers.get("X-Access-Key", "").strip()
            auth_header = self.headers.get("Authorization", "").strip()
            if auth_header.lower().startswith("bearer "):
                bearer_key = auth_header[7:].strip()
            else:
                bearer_key = ""
            body_key = (data or {}).get("passcode", "").strip() if isinstance(data, dict) else ""
            return PASSCODE in (header_key, bearer_key, body_key)

        def do_OPTIONS(self):
            self.send_response(204)
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS")
            self.send_header("Access-Control-Allow-Headers", "Content-Type, Authorization, X-Access-Key")
            self.end_headers()

        def do_HEAD(self):
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()

        def do_GET(self):
            path = urllib.parse.urlparse(self.path).path
            if path == "/app":
                self._send_html(WEB_APP_HTML)
                return
            if path in ("/", "/health"):
                self._send_json(200, {
                    "status": "ok",
                    "service": "agy-cloud-api-gateway",
                    "version": "2.2.0",
                    "shield": "oregon-single-origin-fifo",
                    "queue_depth": _active_waiting,
                    "default_model": DEFAULT_MODEL,
                    "web_app": "/app",
                    "endpoints": ["/v1/chat/completions", "/v1/prompt", "/v1/models", "/v1/sessions/delete", "/health", "/app"]
                })
                return
            if path == "/v1/models":
                self._send_json(200, {
                    "object": "list",
                    "data": [
                        {"id": m["id"], "object": "model", "created": 1700000000, "owned_by": "antigravity", "description": m["name"]}
                        for m in SUPPORTED_MODELS
                    ]
                })
                return
            self._send_json(404, {"error": f"Unknown endpoint: {path}"})

        def do_POST(self):
            path = urllib.parse.urlparse(self.path).path
            content_len = int(self.headers.get("Content-Length", 0))
            if content_len <= 0:
                self._send_json(400, {"error": "Empty request body"})
                return

            raw_body = self.rfile.read(content_len).decode("utf-8")
            try:
                data = json.loads(raw_body)
            except json.JSONDecodeError:
                self._send_json(400, {"error": "Invalid JSON body"})
                return

            if not self._check_auth(data):
                self._send_json(401, {"error": "Invalid or missing passcode (X-Access-Key)"})
                return

            if path == "/v1/sessions/delete":
                purge_all = bool(data.get("all", False))
                conv_id = data.get("conversation_id", "")
                res = purge_agy_sessions(conv_id=conv_id, purge_all=purge_all)
                code = 200 if res.get("status") == "SUCCESS" else 400
                self._send_json(code, res)
                return

            if path == "/v1/prompt":
                prompt = data.get("prompt", "").strip()
                if not prompt:
                    self._send_json(400, {"error": "Missing required field: prompt"})
                    return
                model = data.get("model", DEFAULT_MODEL)
                effort = data.get("effort")
                conv_id = data.get("conversation_id")
                timeout = int(data.get("timeout", 180))
                try:
                    result, code, stderr = run_agy_shielded(prompt, model=model, effort=effort, conversation_id=conv_id, timeout=timeout)
                    if code != 0 and not result.get("response"):
                        result["error"] = stderr or f"agy exited with code {code}"
                    self._send_json(200 if code == 0 else 502, result)
                except subprocess.TimeoutExpired:
                    self._send_json(504, {"error": f"Request timed out after {timeout}s"})
                except Exception as e:
                    self._send_json(500, {"error": str(e)})
                return

            if path == "/v1/chat/completions":
                messages = data.get("messages", [])
                model = data.get("model", DEFAULT_MODEL)
                effort = data.get("reasoning_effort") or data.get("effort")
                conv_id = data.get("conversation_id")
                if not messages:
                    self._send_json(400, {"error": "Missing required field: messages"})
                    return
                parts = []
                for msg in messages:
                    role = msg.get("role", "user")
                    content = msg.get("content", "")
                    if isinstance(content, list):
                        content = "\n".join(c.get("text", "") for c in content if isinstance(c, dict) and c.get("type") == "text")
                    if role == "system":
                        parts.append(f"[System Instructions]\n{content}")
                    elif role == "assistant":
                        parts.append(f"[Previous Assistant Response]\n{content}")
                    else:
                        parts.append(content)
                prompt = "\n\n".join(parts) if len(parts) > 1 else (parts[0] if parts else "")
                try:
                    result, code, stderr = run_agy_shielded(prompt, model=model, effort=effort, conversation_id=conv_id)
                    usage = result.get("usage", {})
                    resp_payload = {
                        "id": result.get("conversation_id", f"chatcmpl-{int(time.time())}"),
                        "object": "chat.completion",
                        "created": int(time.time()),
                        "model": result.get("model_used", model),
                        "choices": [{
                            "index": 0,
                            "message": {"role": "assistant", "content": result.get("response", "")},
                            "finish_reason": "stop" if result.get("status") == "SUCCESS" else "error"
                        }],
                        "usage": {
                            "prompt_tokens": usage.get("input_tokens", 0),
                            "completion_tokens": usage.get("output_tokens", 0),
                            "total_tokens": usage.get("total_tokens", 0)
                        }
                    }
                    if code != 0 and not result.get("response"):
                        resp_payload["error"] = stderr or f"agy exited with code {code}"
                    self._send_json(200 if code == 0 else 502, resp_payload)
                except subprocess.TimeoutExpired:
                    self._send_json(504, {"error": "Request timed out after 180s"})
                except Exception as e:
                    self._send_json(500, {"error": str(e)})
                return

            self._send_json(404, {"error": f"Unknown endpoint: {path}"})

    def run():
        server = ThreadingHTTPServer((DEFAULT_HOST, DEFAULT_PORT), AgyHandler)
        print(f"Shielded agy API Gateway v2.2 running on http://{DEFAULT_HOST}:{DEFAULT_PORT} (Oregon Shield Active)")
        sys.stdout.flush()
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            server.server_close()

    run()
    sys.exit(0)
